window.SB_FEED_BODY=window.SB_FEED_BODY||{},Object.assign(window.SB_FEED_BODY,{"pl-library":{src:"act:library",route:"#/atlas/honey/library",cta:"Open the Great Library",title:"Act II · The Great Library",body:"12 stops on this road, from “Silent kn- / gn- / wr- (Old English)” to “Eponyms (Words from People's Names)”."},"li-u12":{src:"concept:79:concept",route:"#/stop/u12",cta:"Open this stop",title:"Silent kn- / gn- / wr- (Old English)",body:"These initial consonant clusters come from Old English and Norse. The first consonant was once pronounced — you can still hear it in German (Knabe = boy, schreiben = to write). English pronunciation shifted; spelling froze."},"lc-u12-0":{src:"concept:79:cards:0",route:"#/stop/u12",cta:"Open this stop",title:"Silent kn- / gn- / wr- (Old English) · WR- (silent W)",body:"wr- cluster from Old English: wraith (ghost), writhe (twist in pain), wrought (past of work), wrath (fury), wreak (inflict), wrest (twist away), wry (twisted/ironic), wring (twist tightly), wren (small bird). All start with a silent w — only the r is heard."},"lc-u12-1":{src:"concept:79:cards:1",route:"#/stop/u12",cta:"Open this stop",title:"Silent kn- / gn- / wr- (Old English) · KN- (silent K)",body:"Old Norse kn- cluster: knight, knave, kneel, knell (sound of a bell), knapsack, knack, knavish, knickers, knob, knoll (small hill), knot. The k was once pronounced — you can still hear it in German Knabe (boy) and Knie (knee)."},"lc-u12-2":{src:"concept:79:cards:2",route:"#/stop/u12",cta:"Open this stop",title:"Silent kn- / gn- / wr- (Old English) · GN- (silent G)",body:"Gnome (small creature), gnarled (twisted), gnash (grind teeth), gnu (wildebeest), gnostic (gnosis = knowledge — the g was always silent in Greek), gnaw (chew persistently), gnarl (twisted lump). The g was once pronounced in Old English — you can still hear it in Italian gnocchi."},"lc-u12-3":{src:"concept:79:cards:3",route:"#/stop/u12",cta:"Open this stop",title:"Silent kn- / gn- / wr- (Old English) · Why Spelling Froze",body:"English pronunciation shifted dramatically during the Great Vowel Shift (1400–1700), but printing was already standardizing spelling before the shift was complete. Spelling froze at a historical pronunciation moment; pronunciation kept moving."},"lc-u12-4":{src:"concept:79:cards:4",route:"#/stop/u12",cta:"Open this stop",title:"Silent kn- / gn- / wr- (Old English) · Bee Strategy",body:'When you hear a word starting with /r/ (like "right" or "raith") that seems literary or archaic, ask for the origin. Old English → consider wr-. When you hear /n/ at the start of a formal or medieval word, ask: could it be kn-? These two patterns explain dozens of common spelling bee words.'},"uq-u12-0":{src:"unit:u12:qs:0",route:"#/stop/u12",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “Silent kn- / gn- / wr- (Old English)”?",opts:["These initial consonant clusters come from Old English and Norse.","Latin ex- = out of.","Latin inter- = between two or more things.","These noun suffixes create abstract nouns from adjectives."],after:"From “Silent kn- / gn- / wr- (Old English)”."}},"uq-u12-1":{src:"unit:u12:qs:1",route:"#/stop/u12",cta:"Open this stop",title:"Which belongs?",play:{q:"Which word belongs to this chapter's family?",opts:["wraith","chocolate","recalcitrant","perfidious"],after:"From “Silent kn- / gn- / wr- (Old English)”."}},"uq-u12-3":{src:"unit:u12:qs:3",route:"#/stop/u12",cta:"Open this stop",title:"Whose hook?",play:{q:"“A ▁▁▁ is like wrath made ghostly — silent, invisible anger haunting you.” — which word is this hook about?",opts:["wraith","writhe","wrought","wrath"],after:"From “Silent kn- / gn- / wr- (Old English)”."}},"wd-wraith":{src:"concept:79:words:0:def",route:"#/word/wraith",cta:"Open the word card",title:"wraith",roman:"RAYTH",body:"a ghost, or a pale ghostly figure",clip:1},"wx-wraith":{src:"concept:79:words:0:ex",route:"#/word/wraith",cta:"Open the word card",title:"In a sentence · wraith",body:"A pale wraith drifted along the castle corridor in the story Gran read us.",clip:1},"wh-wraith":{src:"concept:79:words:0:hook",route:"#/word/wraith",cta:"Open the word card",title:"Remember it · wraith",body:"A wraith is like wrath made ghostly — silent, invisible anger haunting you."},"wo-wraith":{src:"lore:wraith:0",route:"#/word/wraith",cta:"Open the word card",title:"Where it comes from · wraith",body:"Scottish wraith = ghost, apparition (origin uncertain)"},"wd-writhe":{src:"concept:79:words:1:def",route:"#/word/writhe",cta:"Open the word card",title:"writhe",roman:"RIHTH",body:"to move in a twisting or contorted motion, (especially when struggling)",clip:1},"wx-writhe":{src:"concept:79:words:1:ex",route:"#/word/writhe",cta:"Open the word card",title:"In a sentence · writhe",body:"The prisoner writhed in discomfort",clip:1},"wh-writhe":{src:"concept:79:words:1:hook",route:"#/word/writhe",cta:"Open the word card",title:"Remember it · writhe",body:"WRITHE ends in -THE — think 'the snake writhes,' twisting its body into the shape of a TH."},"wd-wrought":{src:"concept:79:words:2:def",route:"#/word/wrought",cta:"Open the word card",title:"wrought",roman:"RAWT",body:"shaped or worked by hand, especially metal",clip:1},"wx-wrought":{src:"concept:79:words:2:ex",route:"#/word/wrought",cta:"Open the word card",title:"In a sentence · wrought",body:"Curling leaves of wrought iron decorated the gate at the bottom of the garden.",clip:1},"wh-wrought":{src:"concept:79:words:2:hook",route:"#/word/wrought",cta:"Open the word card",title:"Remember it · wrought",body:"WROUGHT iron is worked metal — remember the silent W and tricky -OUGHT by thinking 'Workers WROUGHT it.'"},"wd-wrath":{src:"concept:79:words:3:def",route:"#/word/wrath",cta:"Open the word card",title:"wrath",roman:"RATH",body:"intense anger (usually on an epic scale)",clip:1},"wx-wrath":{src:"concept:79:words:3:ex",route:"#/word/wrath",cta:"Open the word card",title:"In a sentence · wrath",body:"The coach's wrath was clear when the team showed up late to the championship game.",clip:1},"wh-wrath":{src:"concept:79:words:3:hook",route:"#/word/wrath",cta:"Open the word card",title:"Remember it · wrath",body:"WRATH rhymes with BATH — when someone's wrath boils over, they're steaming like a hot bath."},"wd-wreak":{src:"concept:79:words:4:def",route:"#/word/wreak",cta:"Open the word card",title:"wreak",roman:"r-EE-k",body:"to inflict or execute as punishment or vengeance",clip:1},"wx-wreak":{src:"concept:79:words:4:ex",route:"#/word/wreak",cta:"Open the word card",title:"In a sentence · wreak",body:"In the myth, the angry sea god vowed to wreak vengeance on the boastful sailors.",clip:1},"wh-wreak":{src:"concept:79:words:4:hook",route:"#/word/wreak",cta:"Open the word card",title:"Remember it · wreak",body:"WREAK havoc has a silent 'w' like WRECK — both 'wreak' and 'wreck' start with 'wr' and suggest destruction."},"wo-wreak":{src:"lore:wreak:0",route:"#/word/wreak",cta:"Open the word card",title:"Where it comes from · wreak",body:"Old English wrecan = to drive, avenge, punish"},"wd-wrest":{src:"concept:79:words:5:def",route:"#/word/wrest",cta:"Open the word card",title:"wrest",roman:"REHST",body:"obtain by seizing forcibly or violently, also metaphorically",clip:1},"wx-wrest":{src:"concept:79:words:5:ex",route:"#/word/wrest",cta:"Open the word card",title:"In a sentence · wrest",body:"wrest the knife from his hands",clip:1},"wh-wrest":{src:"concept:79:words:5:hook",route:"#/word/wrest",cta:"Open the word card",title:"Remember it · wrest",body:"To WREST control you must first wrestle it away — WREST lives inside WRESTle."},"wd-wry":{src:"concept:79:words:6:def",route:"#/word/wry",cta:"Open the word card",title:"wry",roman:"REYE",body:"humorously sarcastic or mocking",clip:1},"wx-wry":{src:"concept:79:words:6:ex",route:"#/word/wry",cta:"Open the word card",title:"In a sentence · wry",body:"With a wry smile, the comedian pointed out that the one day he forgot his umbrella was the day the city received its heaviest rainfall in decades.",clip:1},"wh-wry":{src:"concept:79:words:6:hook",route:"#/word/wry",cta:"Open the word card",title:"Remember it · wry",body:"WRY humor is twisted — three letters, all twisted: silent W, consonant R, sneaky Y acting as a vowel."},"wd-wring":{src:"concept:79:words:7:def",route:"#/word/wring",cta:"Open the word card",title:"wring",roman:"RIHNG",body:"a twisting squeeze",clip:1},"wx-wring":{src:"concept:79:words:7:ex",route:"#/word/wring",cta:"Open the word card",title:"In a sentence · wring",body:"gave the wet cloth a wring",clip:1},"wh-wring":{src:"concept:79:words:7:hook",route:"#/word/wring",cta:"Open the word card",title:"Remember it · wring",body:"To WRING a towel, you need EXTRA force — that silent W is the extra effort you put in."},"wd-wren":{src:"concept:79:words:8:def",route:"#/word/wren",cta:"Open the word card",title:"wren",roman:"REHN",body:"a small brown songbird with a short tail that points upward",clip:1},"wx-wren":{src:"concept:79:words:8:ex",route:"#/word/wren",cta:"Open the word card",title:"In a sentence · wren",body:"A tiny wren perched on the fence post and filled the quiet morning with its surprisingly loud, melodious song.",clip:1},"wh-wren":{src:"concept:79:words:8:hook",route:"#/word/wren",cta:"Open the word card",title:"Remember it · wren",body:"A WREN starts with a silent W — a tiny bird with a tiny hidden letter"},"wd-knave":{src:"concept:79:words:10:def",route:"#/word/knave",cta:"Open the word card",title:"knave",roman:"NAYV",body:"a deceitful and unreliable scoundrel",clip:1},"wx-knave":{src:"concept:79:words:10:ex",route:"#/word/knave",cta:"Open the word card",title:"In a sentence · knave",body:"The villagers warned each other not to trust the traveling merchant, calling him a knave and a cheat.",clip:1},"wh-knave":{src:"concept:79:words:10:hook",route:"#/word/knave",cta:"Open the word card",title:"Remember it · knave",body:"A KNAVE is a K-naughty rogue — the silent K hides his dishonesty just like he hides his tricks."},"wd-knell":{src:"concept:79:words:11:def",route:"#/word/knell",cta:"Open the word card",title:"knell",roman:"NEHL",body:"the sound of a bell rung slowly to announce a death or a funeral or the end of something",clip:1},"wx-knell":{src:"concept:79:words:11:ex",route:"#/word/knell",cta:"Open the word card",title:"In a sentence · knell",body:"As the old church bell sounded its deep, mournful knell across the foggy village, the mourners gathered at the cemetery gate and bowed their heads in solemn silence.",clip:1},"wh-knell":{src:"concept:79:words:11:hook",route:"#/word/knell",cta:"Open the word card",title:"Remember it · knell",body:"A KNELL sounds like a death bell — the silent K tolls like a ghostly gong before the NELL."},"wo-knell":{src:"lore:knell:0",route:"#/word/knell",cta:"Open the word card",title:"Where it comes from · knell",body:"Old English cnyllan (to ring, strike a bell)."},"wd-knapsack":{src:"concept:79:words:12:def",route:"#/word/knapsack",cta:"Open the word card",title:"knapsack",roman:"NA-psak",body:"a bag carried by a strap on your back or shoulder",clip:1},"wx-knapsack":{src:"concept:79:words:12:ex",route:"#/word/knapsack",cta:"Open the word card",title:"In a sentence · knapsack",body:"She slung her knapsack over both shoulders and headed down the dusty path toward camp.",clip:1},"wh-knapsack":{src:"concept:79:words:12:hook",route:"#/word/knapsack",cta:"Open the word card",title:"Remember it · knapsack",body:"A KNAPSACK snaps onto your back — keep the silent K at the front like the buckle."},"wd-knavish":{src:"concept:79:words:13:def",route:"#/word/knavish",cta:"Open the word card",title:"knavish",roman:"NAY-vish",body:"marked by skill in deception",clip:1},"wx-knavish":{src:"concept:79:words:13:ex",route:"#/word/knavish",cta:"Open the word card",title:"In a sentence · knavish",body:"The knavish merchant short-changed every customer who wasn't paying close attention.",clip:1},"wh-knavish":{src:"concept:79:words:13:hook",route:"#/word/knavish",cta:"Open the word card",title:"Remember it · knavish",body:"KNAVISH behavior is sneaky-ISH — the silent K sneaks in front just like a knave would."},"wd-gnome":{src:"concept:79:words:14:def",route:"#/word/gnome",cta:"Open the word card",title:"gnome",roman:"NOHM",body:"a legendary creature resembling a tiny old man; lives in the depths of the earth and guards buried treasure",clip:1},"wx-gnome":{src:"concept:79:words:14:ex",route:"#/word/gnome",cta:"Open the word card",title:"In a sentence · gnome",body:"The old gardener placed a ceramic gnome beside the tulips for good luck.",clip:1},"wh-gnome":{src:"concept:79:words:14:hook",route:"#/word/gnome",cta:"Open the word card",title:"Remember it · gnome",body:"A GNOME lives underground — the silent G hides like the gnome himself, buried beneath the earth with his treasure."},"wd-gnarled":{src:"concept:79:words:15:def",route:"#/word/gnarled",cta:"Open the word card",title:"gnarled",roman:"NAHRLD",body:"twist into a state of deformity",clip:1},"wx-gnarled":{src:"concept:79:words:15:ex",route:"#/word/gnarled",cta:"Open the word card",title:"In a sentence · gnarled",body:"The gnarled old oak at the edge of the field had twisted branches that looked like the fingers of a giant reaching toward the sky.",clip:1},"wh-gnarled":{src:"concept:79:words:15:hook",route:"#/word/gnarled",cta:"Open the word card",title:"Remember it · gnarled",body:"The silent 'gn' is like a knot you can't untangle"},"wd-gnash":{src:"concept:79:words:16:def",route:"#/word/gnash",cta:"Open the word card",title:"gnash",roman:"n-A-sh",body:"is to grind or strike the teeth together",clip:1},"wx-gnash":{src:"concept:79:words:16:ex",route:"#/word/gnash",cta:"Open the word card",title:"In a sentence · gnash",body:"The trapped wolf would gnash its teeth whenever a stranger came too close.",clip:1},"wh-gnash":{src:"concept:79:words:16:hook",route:"#/word/gnash",cta:"Open the word card",title:"Remember it · gnash",body:"The silent 'gn' bites hard: you GNASH your teeth starting with a letter you never hear — G is there, gnashing silently."},"wo-gnash":{src:"lore:gnash:0",route:"#/word/gnash",cta:"Open the word card",title:"Where it comes from · gnash",body:"Old Norse gnasta = to grind the teeth"},"wd-gnu":{src:"concept:79:words:17:def",route:"#/word/gnu",cta:"Open the word card",title:"gnu",roman:"NOO",body:"large African antelope having a head with horns like an ox and a long tufted tail",clip:1},"wx-gnu":{src:"concept:79:words:17:ex",route:"#/word/gnu",cta:"Open the word card",title:"In a sentence · gnu",body:"The documentary showed a gnu charging across the savanna to escape a pursuing lion.",clip:1},"wh-gnu":{src:"concept:79:words:17:hook",route:"#/word/gnu",cta:"Open the word card",title:"Remember it · gnu",body:"A GNU is a new antelope to many — it sounds like 'new' but is spelled gnu, where the G silently stampedes ahead of the n-u."},"wd-gnostic":{src:"concept:79:words:18:def",route:"#/word/gnostic",cta:"Open the word card",title:"gnostic",roman:"NOS-tik",body:"an advocate of Gnosticism",clip:1},"wx-gnostic":{src:"concept:79:words:18:ex",route:"#/word/gnostic",cta:"Open the word card",title:"In a sentence · gnostic",body:"The professor explained that a gnostic believes salvation comes through secret spiritual knowledge rather than faith alone, and that these ancient thinkers often clashed sharply with the mainstream religious authorities of their time.",clip:1},"wh-gnostic":{src:"concept:79:words:18:hook",route:"#/word/gnostic",cta:"Open the word card",title:"Remember it · gnostic",body:"A GNOSTIC seeks hidden knowledge — that silent G hides the secret just as Gnostic wisdom was hidden from ordinary people."},"li-u13":{src:"concept:80:concept",route:"#/stop/u13",cta:"Open this stop",title:"Silent -gh- Patterns",body:"The -gh- cluster is Old English's most complex legacy. It was once pronounced as a guttural /kh/ sound (like German Bach). As that sound disappeared, the gh became silent — but stayed in the spelling, creating six different pronunciations for -ough alone."},"lc-u13-0":{src:"concept:80:cards:0",route:"#/stop/u13",cta:"Open this stop",title:"Silent -gh- Patterns · -igh- = /eye/ sound",body:"Night, knight, blight, flight, right, sight, tight, light, might, slight, fright, plight, bright. The -igh- sequence always = /eye/. The gh is completely silent. This is the most regular of the -gh- patterns."},"lc-u13-1":{src:"concept:80:cards:1",route:"#/stop/u13",cta:"Open this stop",title:"Silent -gh- Patterns · -ough = 6 pronunciations (memorize as groups)",body:"- /oh/: though, although, dough, furlough - /oo/: through, slough (a swamp) - /uf/: rough, tough, enough, slough (shed skin) - /of/: cough, trough - /aw/: thought, bought, fought, ought, nought, distraught, wrought - /up/: hiccough (= hiccup) Learn by pronunciation group, not individual words."},"lc-u13-2":{src:"concept:80:cards:2",route:"#/stop/u13",cta:"Open this stop",title:"Silent -gh- Patterns · -aught = /awt/ sound",body:"Distraught (pulled apart = extremely upset), onslaught (sudden violent attack), slaughter, naught (nothing), naughty, daughter, caught, taught, fraught (filled with anxiety). All use -aught = /awt/. This group is the most consistent."},"lc-u13-3":{src:"concept:80:cards:3",route:"#/stop/u13",cta:"Open this stop",title:"Silent -gh- Patterns · -ight vs -ite",body:"Night (Old English, -ight) vs site (Latin, -ite). Might (power) vs mite (a tiny creature). Right vs write vs rite — three spellings of one /rīt/ sound. When the /eye/ + /t/ sound appears in a word with Old English feel, the spelling is likely -ight."},"lc-u13-4":{src:"concept:80:cards:4",route:"#/stop/u13",cta:"Open this stop",title:"Silent -gh- Patterns · Bee Strategy for -gh-",body:"Ask for origin and definition. Old English origin + /awt/ sound → -aught. Old English + /eye/ sound → -ight. The /uf/ sound in a short word → likely -ough (rough, tough). The /oh/ sound in a word → could be -ough (though) or -ow (low) — definition distinguishes."},"uq-u13-0":{src:"unit:u13:qs:0",route:"#/stop/u13",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “Silent -gh- Patterns”?",opts:["The -gh- cluster is Old English's most complex legacy.","Latin ex- = out of.","Latin inter- = between two or more things.","These noun suffixes create abstract nouns from adjectives."],after:"From “Silent -gh- Patterns”."}},"uq-u13-3":{src:"unit:u13:qs:3",route:"#/stop/u13",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁ — the GH is silent but the emotion is not; the AU combination sounds like AW in 'awful.'” — which word is this hook about?",opts:["distraught","onslaught","slaughter","naught"],after:"From “Silent -gh- Patterns”."}},"wd-distraught":{src:"concept:80:words:0:def",route:"#/word/distraught",cta:"Open the word card",title:"distraught",roman:"d-ih-s-t-r-AW-t",body:"means deeply agitated",clip:1},"wx-distraught":{src:"concept:80:words:0:ex",route:"#/word/distraught",cta:"Open the word card",title:"In a sentence · distraught",body:"distraught with grief",clip:1},"wh-distraught":{src:"concept:80:words:0:hook",route:"#/word/distraught",cta:"Open the word card",title:"Remember it · distraught",body:"DISTRAUGHT — the GH is silent but the emotion is not; the AU combination sounds like AW in 'awful.'"},"wo-distraught":{src:"lore:distraught:0",route:"#/word/distraught",cta:"Open the word card",title:"Where it comes from · distraught",body:"Latin distractus = pulled apart, past participle of distrahere"},"wd-onslaught":{src:"concept:80:words:1:def",route:"#/word/onslaught",cta:"Open the word card",title:"onslaught",roman:"AW-nslawt",body:"a sudden and severe onset of trouble",clip:1},"wx-onslaught":{src:"concept:80:words:1:ex",route:"#/word/onslaught",cta:"Open the word card",title:"In a sentence · onslaught",body:"An onslaught of hail flattened every tomato plant in under a minute.",clip:1},"wh-onslaught":{src:"concept:80:words:1:hook",route:"#/word/onslaught",cta:"Open the word card",title:"Remember it · onslaught",body:"ONSLAUGHT — remember the AUGHT at the end like 'caught' or 'taught'; the attack CAUGHT everyone off guard."},"wd-naught":{src:"concept:80:words:3:def",route:"#/word/naught",cta:"Open the word card",title:"naught",roman:"NAWT",body:"a quantity of no importance",clip:1},"wx-naught":{src:"concept:80:words:3:ex",route:"#/word/naught",cta:"Open the word card",title:"In a sentence · naught",body:"All that practice came to naught when rain cancelled the final match.",clip:1},"wh-naught":{src:"concept:80:words:3:hook",route:"#/word/naught",cta:"Open the word card",title:"Remember it · naught",body:"NAUGHT has the AUGH pattern — think 'All Ugh, I got nothing!'"},"wd-naughty":{src:"concept:80:words:4:def",route:"#/word/naughty",cta:"Open the word card",title:"naughty",roman:"NAW-tee",body:"suggestive of sexual impropriety",clip:1},"wx-naughty":{src:"concept:80:words:4:ex",route:"#/word/naughty",cta:"Open the word card",title:"In a sentence · naughty",body:"The comedian's naughty jokes made some adults in the audience blush, though they tried to hide their laughter behind their programs.",clip:1},"wh-naughty":{src:"concept:80:words:4:hook",route:"#/word/naughty",cta:"Open the word card",title:"Remember it · naughty",body:"NAUGHTY has NAUGHT inside — a naughty child has naught (no) good behavior."},"wd-daughter":{src:"concept:80:words:5:def",route:"#/word/daughter",cta:"Open the word card",title:"daughter",roman:"DAW-ter",body:"a female human offspring",clip:1},"wx-daughter":{src:"concept:80:words:5:ex",route:"#/word/daughter",cta:"Open the word card",title:"In a sentence · daughter",body:"My grandmother beamed with pride as her daughter—my mother—walked across the stage to receive her college diploma.",clip:1},"wh-daughter":{src:"concept:80:words:5:hook",route:"#/word/daughter",cta:"Open the word card",title:"Remember it · daughter",body:"DAUGHTER has a silent GH in the middle—think AUGHT like 'taught'"},"wo-daughter":{src:"lore:daughter:0",route:"#/word/daughter",cta:"Open the word card",title:"Where it comes from · daughter",body:"Old English dohtor = female child; cognate with German Tochter"},"wd-fraught":{src:"concept:80:words:6:def",route:"#/word/fraught",cta:"Open the word card",title:"fraught",roman:"f-r-AW-t",body:"means full of or accompanied by",clip:1},"wx-fraught":{src:"concept:80:words:6:ex",route:"#/word/fraught",cta:"Open the word card",title:"In a sentence · fraught",body:"a fraught mother-daughter relationship",clip:1},"wh-fraught":{src:"concept:80:words:6:hook",route:"#/word/fraught",cta:"Open the word card",title:"Remember it · fraught",body:"FRAUGHT rhymes with CAUGHT—you get caught in a fraught situation"},"wo-fraught":{src:"lore:fraught:0",route:"#/word/fraught",cta:"Open the word card",title:"Where it comes from · fraught",body:"Middle Dutch vracht = ship's cargo (originally 'laden with')"},"wd-thought":{src:"concept:80:words:8:def",route:"#/word/thought",cta:"Open the word card",title:"thought",roman:"THAWT",body:"the content of cognition; the main thing you are thinking about",clip:1},"wx-thought":{src:"concept:80:words:8:ex",route:"#/word/thought",cta:"Open the word card",title:"In a sentence · thought",body:"One thought kept circling in Leo's head, the worry that he had left the rabbit hutch open.",clip:1},"wh-thought":{src:"concept:80:words:8:hook",route:"#/word/thought",cta:"Open the word card",title:"Remember it · thought",body:"THOUGHT contains 'ought' — you OUGHT to think (thought) before you speak."},"wo-thought":{src:"lore:thought:0",route:"#/word/thought",cta:"Open the word card",title:"Where it comes from · thought",body:"Old English þōht = act of thinking"},"wd-bought":{src:"concept:80:words:9:def",route:"#/word/bought",cta:"Open the word card",title:"bought",roman:"BAHT",body:"obtain by purchase; acquire by means of a financial transaction",clip:1},"wx-bought":{src:"concept:80:words:9:ex",route:"#/word/bought",cta:"Open the word card",title:"In a sentence · bought",body:"With her saved pocket money, Amira bought a second-hand bicycle and painted it blue.",clip:1},"wh-bought":{src:"concept:80:words:9:hook",route:"#/word/bought",cta:"Open the word card",title:"Remember it · bought",body:"You BOUGHT it with cash and got a silent 'ugh' deal — no 'a', just 'ou' like you 'ought' to remember."},"wd-blight":{src:"concept:80:words:11:def",route:"#/word/blight",cta:"Open the word card",title:"blight",roman:"BLEYET",body:"a state or condition being blighted",clip:1},"wx-blight":{src:"concept:80:words:11:ex",route:"#/word/blight",cta:"Open the word card",title:"In a sentence · blight",body:"Too much rain may blight the garden with mold",clip:1},"wh-blight":{src:"concept:80:words:11:hook",route:"#/word/blight",cta:"Open the word card",title:"Remember it · blight",body:"A BLIGHT makes crops look SLIGHT — both end in -IGHT: B-L-I-G-H-T."},"wo-blight":{src:"lore:blight:0",route:"#/word/blight",cta:"Open the word card",title:"Where it comes from · blight",body:"Old English blæcan = to bleach or make pale, associated with disease causing pallor"},"wd-plough":{src:"concept:80:words:12:def",route:"#/word/plough",cta:"Open the word card",title:"plough",roman:"PLOW",body:"a group of seven bright stars in the constellation Ursa Major",clip:1},"wx-plough":{src:"concept:80:words:12:ex",route:"#/word/plough",cta:"Open the word card",title:"In a sentence · plough",body:"On clear nights Dad points out the Plough, seven bright stars shaped like a saucepan.",clip:1},"wh-plough":{src:"concept:80:words:12:hook",route:"#/word/plough",cta:"Open the word card",title:"Remember it · plough",body:"The British PLOUGH hides OUGH like THROUGH—think of the plow CUTTING THROUGH the soil."},"wd-though":{src:"concept:80:words:13:def",route:"#/word/though",cta:"Open the word card",title:"though",roman:"THOH",body:"(postpositive) however",clip:1},"wx-though":{src:"concept:80:words:13:ex",route:"#/word/though",cta:"Open the word card",title:"In a sentence · though",body:"it might be unpleasant, though",clip:1},"wh-though":{src:"concept:80:words:13:hook",route:"#/word/though",cta:"Open the word card",title:"Remember it · though",body:"'Though' looks like 'through' lost its 'r' — it's a long spelling for a word that means 'even so.'"},"wd-through":{src:"concept:80:words:14:def",route:"#/word/through",cta:"Open the word card",title:"through",roman:"THROO",body:"having finished or arrived at completion",clip:1},"wx-through":{src:"concept:80:words:14:ex",route:"#/word/through",cta:"Open the word card",title:"In a sentence · through",body:"Once you are through with your homework, we can walk down to the river.",clip:1},"wh-through":{src:"concept:80:words:14:hook",route:"#/word/through",cta:"Open the word card",title:"Remember it · through",body:"THROUGH is TOUGH to spell — just remember: THR + OUGH, like ROUGH but with a TH in front."},"wd-rough":{src:"concept:80:words:15:def",route:"#/word/rough",cta:"Open the word card",title:"rough",roman:"RUHF",body:"the part of a golf course bordering the fairway where the grass is not cut short",clip:1},"wx-rough":{src:"concept:80:words:15:ex",route:"#/word/rough",cta:"Open the word card",title:"In a sentence · rough",body:"trees with rough bark",clip:1},"wh-rough":{src:"concept:80:words:15:hook",route:"#/word/rough",cta:"Open the word card",title:"Remember it · rough",body:"ROUGH has a tricky OUGH that sounds like UFF — think 'it's ROUGH enough to trip you up with that spelling.'"},"wd-cough":{src:"concept:80:words:16:def",route:"#/word/cough",cta:"Open the word card",title:"cough",roman:"k-AH-f",body:"is to expel air through the lungs harshly often violently",clip:1},"wx-cough":{src:"concept:80:words:16:ex",route:"#/word/cough",cta:"Open the word card",title:"In a sentence · cough",body:"The smoker coughs all day",clip:1},"wh-cough":{src:"concept:80:words:16:hook",route:"#/word/cough",cta:"Open the word card",title:"Remember it · cough",body:"A ROUGH cough is TOUGH enough — all three share the '-ough' that sounds like '-uff'."},"wo-cough":{src:"lore:cough:0",route:"#/word/cough",cta:"Open the word card",title:"Where it comes from · cough",body:"Old English cohhian = to cough"},"li-u14":{src:"concept:81:concept",route:"#/stop/u14",cta:"Open this stop",title:"ie / ei Rule and Exceptions",body:'The classic rhyme: "i before e, except after c, or when sounding like /ay/ as in neighbor and weigh." This covers 80% of cases. The other 20% — the exceptions — are the ones that appear in spelling bees.'},"lc-u14-0":{src:"concept:81:cards:0",route:"#/stop/u14",cta:"Open this stop",title:"ie / ei Rule and Exceptions · The Rule — i before e",body:'After most consonants, ie = /ee/: believe, achieve, relieve, reprieve, grieve, retrieve, mischief, piece, niece. The mnemonic: "i before e" — the i comes first in most /ee/ sounds.'},"lc-u14-1":{src:"concept:81:cards:1",route:"#/stop/u14",cta:"Open this stop",title:"ie / ei Rule and Exceptions · After c — e before i",body:"After the letter c, the order reverses: ceiling, receive, perceive, deceive, conceive, deceit, conceit, receipt. The c flips the order. Mnemonic: the c is selfish — it pushes e in front of i."},"lc-u14-2":{src:"concept:81:cards:2",route:"#/stop/u14",cta:"Open this stop",title:"ie / ei Rule and Exceptions · When Sounding /ay/ — e before i",body:"Vein, reign, rein, sleigh, weigh, beige, feign, feint, freight, neighbor, eight. When the vowel combination sounds like /ay/, e comes before i. The sound /ay/ overrides the normal order."},"lc-u14-3":{src:"concept:81:cards:3",route:"#/stop/u14",cta:"Open this stop",title:"ie / ei Rule and Exceptions · The Exceptions — Memorize These",body:"Seize (not sieze), weird (not wierd), either (not iether), neither, leisure (not liesure), forfeit (not forfiet), foreign (not foriegn), height (not hieght), protein, caffeine, kaleidoscope, zeitgeist, species. These break the rule and must be memorized individually."},"lc-u14-4":{src:"concept:81:cards:4",route:"#/stop/u14",cta:"Open this stop",title:"ie / ei Rule and Exceptions · Why the Rule Has Exceptions",body:"The rule was invented in 1866 to describe English spelling — English spelling was not invented to follow the rule."},"uq-u14-0":{src:"unit:u14:qs:0",route:"#/stop/u14",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “ie / ei Rule and Exceptions”?",opts:['The classic rhyme: "i before e, except after c, or when sounding like /ay/ as in neighbor and weigh." This covers 80% of cases.',"Latin ex- = out of.","Latin inter- = between two or more things.","These noun suffixes create abstract nouns from adjectives."],after:"From “ie / ei Rule and Exceptions”."}},"uq-u14-3":{src:"unit:u14:qs:3",route:"#/stop/u14",cta:"Open this stop",title:"Whose hook?",play:{q:"“Never ▁▁▁ a LIE — the word '▁▁▁' hides the word LIE right in the middle!” — which word is this hook about?",opts:["believe","achieve","relieve","ceiling"],after:"From “ie / ei Rule and Exceptions”."}},"wd-believe":{src:"concept:81:words:0:def",route:"#/word/believe",cta:"Open the word card",title:"believe",roman:"bih-LEEV",body:"accept as true; take to be true",clip:1},"wx-believe":{src:"concept:81:words:0:ex",route:"#/word/believe",cta:"Open the word card",title:"In a sentence · believe",body:"I believed his report",clip:1},"wh-believe":{src:"concept:81:words:0:hook",route:"#/word/believe",cta:"Open the word card",title:"Remember it · believe",body:"Never beLIEve a LIE — the word 'believe' hides the word LIE right in the middle!"},"wd-achieve":{src:"concept:81:words:1:def",route:"#/word/achieve",cta:"Open the word card",title:"achieve",roman:"uh-CHEEV",body:"to gain with effort",clip:1},"wx-achieve":{src:"concept:81:words:1:ex",route:"#/word/achieve",cta:"Open the word card",title:"In a sentence · achieve",body:"she achieved her goal despite setbacks",clip:1},"wh-achieve":{src:"concept:81:words:1:hook",route:"#/word/achieve",cta:"Open the word card",title:"Remember it · achieve",body:"The CHIEF leads the team — aCHIEve has CHIEF hidden inside: a-CHIE-ve."},"wd-relieve":{src:"concept:81:words:2:def",route:"#/word/relieve",cta:"Open the word card",title:"relieve",roman:"r-ih-l-EE-v",body:"is to ease or alleviate pain distress or anxiety",clip:1},"wx-relieve":{src:"concept:81:words:2:ex",route:"#/word/relieve",cta:"Open the word card",title:"In a sentence · relieve",body:"This pill will relieve your headaches",clip:1},"wh-relieve":{src:"concept:81:words:2:hook",route:"#/word/relieve",cta:"Open the word card",title:"Remember it · relieve",body:"RELIEVE: I before E — reLIEve the pain by letting it LIE down first."},"wo-relieve":{src:"lore:relieve:0",route:"#/word/relieve",cta:"Open the word card",title:"Where it comes from · relieve",body:"Old French relever = to raise up, lighten"},"wd-ceiling":{src:"concept:81:words:3:def",route:"#/word/ceiling",cta:"Open the word card",title:"ceiling",roman:"SEE-lihng",body:"the overhead upper surface of a covered space",clip:1},"wx-ceiling":{src:"concept:81:words:3:ex",route:"#/word/ceiling",cta:"Open the word card",title:"In a sentence · ceiling",body:"he hated painting the ceiling",clip:1},"wh-ceiling":{src:"concept:81:words:3:hook",route:"#/word/ceiling",cta:"Open the word card",title:"Remember it · ceiling",body:"The CEILING follows the 'I before E' rule's exception — remember: you CEIl the room, and the ceiling is above you."},"wd-receive":{src:"concept:81:words:4:def",route:"#/word/receive",cta:"Open the word card",title:"receive",roman:"ruh-SEEV",body:"get something; come into possession of",clip:1},"wx-receive":{src:"concept:81:words:4:ex",route:"#/word/receive",cta:"Open the word card",title:"In a sentence · receive",body:"At the end-of-year ceremony, every student who completed the reading challenge would receive a personalized certificate and a gift card to the local bookstore as a reward for their efforts.",clip:1},"wh-receive":{src:"concept:81:words:4:hook",route:"#/word/receive",cta:"Open the word card",title:"Remember it · receive",body:"Break the I-before-E rule: reCEIVE — think 'CEIling' to remember CEI, not CIE."},"wd-perceive":{src:"concept:81:words:5:def",route:"#/word/perceive",cta:"Open the word card",title:"perceive",roman:"p-ur-s-EE-v",body:"is to become aware of",clip:1},"wx-perceive":{src:"concept:81:words:5:ex",route:"#/word/perceive",cta:"Open the word card",title:"In a sentence · perceive",body:"I could perceive the ship coming over the horizon",clip:1},"wh-perceive":{src:"concept:81:words:5:hook",route:"#/word/perceive",cta:"Open the word card",title:"Remember it · perceive",body:"Remember: I before E except after C — perCEIVE has C-E-I-V-E, not C-I-E."},"wo-perceive":{src:"lore:perceive:0",route:"#/word/perceive",cta:"Open the word card",title:"Where it comes from · perceive",body:"Latin percipere = to seize, grasp, from per-(thoroughly)+capere(to take)"},"wd-deceive":{src:"concept:81:words:6:def",route:"#/word/deceive",cta:"Open the word card",title:"deceive",roman:"d-ih-s-EE-v",body:"is to mislead by a false appearance or statement",clip:1},"wx-deceive":{src:"concept:81:words:6:ex",route:"#/word/deceive",cta:"Open the word card",title:"In a sentence · deceive",body:"The insurance company deceived me when they told me they were covering my house",clip:1},"wh-deceive":{src:"concept:81:words:6:hook",route:"#/word/deceive",cta:"Open the word card",title:"Remember it · deceive",body:"deCEIVE — the E comes before I here: 'CEI' not 'CIE' — the deceiver puts E before I to trick you!"},"wo-deceive":{src:"lore:deceive:0",route:"#/word/deceive",cta:"Open the word card",title:"Where it comes from · deceive",body:"Latin decipere = to ensnare, from de- + capere = to take"},"wd-vein":{src:"concept:81:words:7:def",route:"#/word/vein",cta:"Open the word card",title:"vein",roman:"VAYN",body:"a blood vessel that carries blood from the capillaries toward the heart",clip:1},"wx-vein":{src:"concept:81:words:7:ex",route:"#/word/vein",cta:"Open the word card",title:"In a sentence · vein",body:"all veins except the pulmonary vein carry unaerated blood",clip:1},"wh-vein":{src:"concept:81:words:7:hook",route:"#/word/vein",cta:"Open the word card",title:"Remember it · vein",body:"A VEIN carries blood — E before I: 'thE blood In a VEIN flows to the heart.'"},"wo-vein":{src:"lore:vein:0",route:"#/word/vein",cta:"Open the word card",title:"Where it comes from · vein",body:"Latin vena = blood vessel, channel"},"wd-reign":{src:"concept:81:words:8:def",route:"#/word/reign",cta:"Open the word card",title:"reign",roman:"RAYN",body:"a period during which something or somebody is dominant or powerful",clip:1},"wx-reign":{src:"concept:81:words:8:ex",route:"#/word/reign",cta:"Open the word card",title:"In a sentence · reign",body:"he was helpless under the reign of his egotism",clip:1},"wh-reign":{src:"concept:81:words:8:hook",route:"#/word/reign",cta:"Open the word card",title:"Remember it · reign",body:"REIGN contains a silent G-N — the KING's REIGN has a silent G like the silent power of royalty; R-E-I-G-N."},"wd-feign":{src:"concept:81:words:9:def",route:"#/word/feign",cta:"Open the word card",title:"feign",roman:"f-AY-n",body:"is to represent fictitiously",clip:1},"wx-feign":{src:"concept:81:words:9:ex",route:"#/word/feign",cta:"Open the word card",title:"In a sentence · feign",body:"He feigned that he was ill",clip:1},"wh-feign":{src:"concept:81:words:9:hook",route:"#/word/feign",cta:"Open the word card",title:"Remember it · feign",body:"FEIGN has a hidden GN — you feign ignorance by hiding the G like a silent secret."},"wo-feign":{src:"lore:feign:0",route:"#/word/feign",cta:"Open the word card",title:"Where it comes from · feign",body:"Old French feindre = to pretend, from Latin fingere = to shape, pretend"},"wd-seize":{src:"concept:81:words:10:def",route:"#/word/seize",cta:"Open the word card",title:"seize",roman:"SEEZ",body:"take hold of; grab",clip:1},"wx-seize":{src:"concept:81:words:10:ex",route:"#/word/seize",cta:"Open the word card",title:"In a sentence · seize",body:"The detective moved quickly to seize the evidence before it could be destroyed.",clip:1},"wh-seize":{src:"concept:81:words:10:hook",route:"#/word/seize",cta:"Open the word card",title:"Remember it · seize",body:"SEIZE breaks the 'i before e' rule — remember: weird SEIZURE"},"wo-seize":{src:"lore:seize:0",route:"#/word/seize",cta:"Open the word card",title:"Where it comes from · seize",body:"Old French 'saisir' = to take possession of, from Frankish 'sakjan' = to lay claim to"},"wd-weird":{src:"concept:81:words:11:def",route:"#/word/weird",cta:"Open the word card",title:"weird",roman:"w-IH-r-d",body:"is unearthly or uncanny",clip:1},"wx-weird":{src:"concept:81:words:11:ex",route:"#/word/weird",cta:"Open the word card",title:"In a sentence · weird",body:"It felt truly weird to walk through the empty school hallways on a Tuesday afternoon when every student and teacher had left early for a surprise snow day.",clip:1},"wh-weird":{src:"concept:81:words:11:hook",route:"#/word/weird",cta:"Open the word card",title:"Remember it · weird",body:"WEIRD breaks the 'i before e' rule — it's so WEIRD that E comes before I!"},"wo-weird":{src:"lore:weird:0",route:"#/word/weird",cta:"Open the word card",title:"Where it comes from · weird",body:"Old English wyrd = fate, destiny"},"wd-neither":{src:"concept:81:words:12:def",route:"#/word/neither",cta:"Open the word card",title:"neither",roman:"NEE-ther",body:"not either; not one or the other",clip:1},"wx-neither":{src:"concept:81:words:12:ex",route:"#/word/neither",cta:"Open the word card",title:"In a sentence · neither",body:"Neither the rain nor the cold could keep the determined runners from finishing the marathon.",clip:1},"wh-neither":{src:"concept:81:words:12:hook",route:"#/word/neither",cta:"Open the word card",title:"Remember it · neither",body:"Neither follows the E-I rule exception: N-E-I-T-H-E-R — think 'not either' shrunk to one word."},"wd-leisure":{src:"concept:81:words:13:def",route:"#/word/leisure",cta:"Open the word card",title:"leisure",roman:"l-EH-zh-ur",body:"is freedom from the demands of work",clip:1},"wx-leisure":{src:"concept:81:words:13:ex",route:"#/word/leisure",cta:"Open the word card",title:"In a sentence · leisure",body:"his job left him little leisure",clip:1},"wh-leisure":{src:"concept:81:words:13:hook",route:"#/word/leisure",cta:"Open the word card",title:"Remember it · leisure",body:"LEIsure — think of LEI (a flower necklace): relaxing on a Hawaiian vacation is leisure!"},"wo-leisure":{src:"lore:leisure:0",route:"#/word/leisure",cta:"Open the word card",title:"Where it comes from · leisure",body:"Old French leisir = to be permitted, from Latin licere = to be lawful/permitted"},"wd-forfeit":{src:"concept:81:words:14:def",route:"#/word/forfeit",cta:"Open the word card",title:"forfeit",roman:"FAW-rfiht",body:"something that is lost or surrendered as a penalty",clip:1},"wx-forfeit":{src:"concept:81:words:14:ex",route:"#/word/forfeit",cta:"Open the word card",title:"In a sentence · forfeit",body:"Because three players missed the mandatory practice, the team had to forfeit their spot in the championship tournament.",clip:1},"wh-forfeit":{src:"concept:81:words:14:hook",route:"#/word/forfeit",cta:"Open the word card",title:"Remember it · forfeit",body:"FORFEIT: remember E before I here—it's one of the exceptions to 'i before e'"},"wd-foreign":{src:"concept:81:words:15:def",route:"#/word/foreign",cta:"Open the word card",title:"foreign",roman:"FAW-ruhn",body:"of concern to or concerning the affairs of other nations (other than your own)",clip:1},"wx-foreign":{src:"concept:81:words:15:ex",route:"#/word/foreign",cta:"Open the word card",title:"In a sentence · foreign",body:"Learning a foreign language can open doors to new cultures, friendships, and opportunities that most people in your hometown never get the chance to experience.",clip:1},"wh-foreign":{src:"concept:81:words:15:hook",route:"#/word/foreign",cta:"Open the word card",title:"Remember it · foreign",body:"FOREIGN hides a REIGN inside — a foreign king has a reign far away; remember i before e except after c, but here it's E-I-G-N."},"wd-height":{src:"concept:81:words:16:def",route:"#/word/height",cta:"Open the word card",title:"height",roman:"HEYET",body:"the vertical dimension of extension; distance from the base of something to the top",clip:1},"wx-height":{src:"concept:81:words:16:ex",route:"#/word/height",cta:"Open the word card",title:"In a sentence · height",body:"We measured the sunflower's height and found it had grown past the garden fence.",clip:1},"wh-height":{src:"concept:81:words:16:hook",route:"#/word/height",cta:"Open the word card",title:"Remember it · height",body:"HEIGHT has a silent GH — think 'High Enormous Incredible Giant Huge Thing.'"},"wd-protein":{src:"concept:81:words:17:def",route:"#/word/protein",cta:"Open the word card",title:"protein",roman:"PROH-teen",body:"any of a large group of nitrogenous organic compounds that are essential constituents of living cells; consist of polymers of amino acids; essential in the diet of animals for growth and for repair of tissues; can be obtained from meat and eggs and milk and legumes",clip:1},"wx-protein":{src:"concept:81:words:17:ex",route:"#/word/protein",cta:"Open the word card",title:"In a sentence · protein",body:"a diet high in protein",clip:1},"wh-protein":{src:"concept:81:words:17:hook",route:"#/word/protein",cta:"Open the word card",title:"Remember it · protein",body:"Remember: E before I — 'prote-IN,' not 'proti-EN' — protein comes FIRST (protos) in your diet."},"wd-caffeine":{src:"concept:81:words:18:def",route:"#/word/caffeine",cta:"Open the word card",title:"caffeine",roman:"ka-FEEN",body:"a bitter alkaloid found in coffee and tea that is responsible for their stimulating effects",clip:1},"wx-caffeine":{src:"concept:81:words:18:ex",route:"#/word/caffeine",cta:"Open the word card",title:"In a sentence · caffeine",body:"Maya limited herself to one cup of tea in the morning because too much caffeine made her hands jittery during her violin recital.",clip:1},"wh-caffeine":{src:"concept:81:words:18:hook",route:"#/word/caffeine",cta:"Open the word card",title:"Remember it · caffeine",body:"Caffeine has DOUBLE F — two shots of espresso, two F's."},"li-u15":{src:"concept:82:concept",route:"#/stop/u15",cta:"Open this stop",title:"Double Consonant Rules",body:"English doubles a final consonant before suffixes that begin with a vowel (-ing, -ed, -er, -est) under specific conditions. The rule is completely systematic — stress is the key."},"lc-u15-0":{src:"concept:82:cards:0",route:"#/stop/u15",cta:"Open this stop",title:"Double Consonant Rules · The One-Syllable Rule (CVC)",body:"Double the final consonant when a one-syllable word ends in consonant-vowel-consonant: run→running, stop→stopped, sit→sitting, cut→cutting, big→bigger. The doubling keeps the vowel short. Without it: runing would rhyme with tuning."},"lc-u15-1":{src:"concept:82:cards:1",route:"#/stop/u15",cta:"Open this stop",title:"Double Consonant Rules · The Two-Syllable Stress Rule",body:"For two-syllable words, double only if stress falls on the LAST syllable: begin→beginning (stress on BEGIN), occur→occurred (stress on OCCUR), commit→committed (stress on COMMIT), prefer→preferred (stress on preFER). Do NOT double if stress falls on the FIRST syllable: open→opening, happen→happened."},"lc-u15-2":{src:"concept:82:cards:2",route:"#/stop/u15",cta:"Open this stop",title:"Double Consonant Rules · Test — Tap the Syllable",body:"Tap your desk on each syllable and feel which one is louder. Travel: TRAV-el (first syllable louder) → traveled (no double). Control: con-TROL (second syllable louder) → controlled (double-l). Offer: OF-fer (first) → offered (no double). Occur: oc-CUR (second) → occurred (double-r)."},"lc-u15-3":{src:"concept:82:cards:3",route:"#/stop/u15",cta:"Open this stop",title:"Double Consonant Rules · American vs British Doubling",body:"Americans: traveled, modeled, canceled. British: travelled, modelled, cancelled — they double whenever the final l is preceded by a single vowel, regardless of stress. For US spelling bees (Merriam-Webster): American conventions apply. Know which dictionary the bee uses."},"lc-u15-4":{src:"concept:82:cards:4",route:"#/stop/u15",cta:"Open this stop",title:"Double Consonant Rules · Always-Doubled Words",body:"Some words have inherited double consonants that are not about suffixes — they must be memorized: accommodate (double-c + double-m), embarrass (double-r + double-s), millennium (double-l + double-n), necessary (one-c + double-s), occasion (double-c + one-s), recommend (one-c + double-m), satellite (one-t + double-l)."},"uq-u15-0":{src:"unit:u15:qs:0",route:"#/stop/u15",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “Double Consonant Rules”?",opts:["English doubles a final consonant before suffixes that begin with a vowel (-ing, -ed, -er, -est) under specific conditions.","Latin ex- = out of.","Latin inter- = between two or more things.","These noun suffixes create abstract nouns from adjectives."],after:"From “Double Consonant Rules”."}},"uq-u15-3":{src:"unit:u15:qs:3",route:"#/stop/u15",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁ doubles the T in past tense — you were so ▁▁▁ you gave it two T's!” — which word is this hook about?",opts:["committed","occurred","beginning","preferred"],after:"From “Double Consonant Rules”."}},"wd-committed":{src:"concept:82:words:0:def",route:"#/word/committed",cta:"Open the word card",title:"committed",roman:"kuh-MIH-tihd",body:"perform an act, usually with a negative connotation",clip:1},"wx-committed":{src:"concept:82:words:0:ex",route:"#/word/committed",cta:"Open the word card",title:"In a sentence · committed",body:"The detective announced that a crime had been committed sometime between midnight and dawn, and that all residents of the building were considered potential witnesses.",clip:1},"wh-committed":{src:"concept:82:words:0:hook",route:"#/word/committed",cta:"Open the word card",title:"Remember it · committed",body:"comMITTED doubles the T in past tense — you were so committed you gave it two T's!"},"wo-committed":{src:"lore:committed:0",route:"#/word/committed",cta:"Open the word card",title:"Where it comes from · committed",body:"Latin committere = to send or put together"},"wd-occurred":{src:"concept:82:words:1:def",route:"#/word/occurred",cta:"Open the word card",title:"occurred",roman:"uh-KURD",body:"come to pass",clip:1},"wx-occurred":{src:"concept:82:words:1:ex",route:"#/word/occurred",cta:"Open the word card",title:"In a sentence · occurred",body:"A tremendous thunderstorm occurred overnight, knocking out the power and leaving the entire neighborhood in darkness until repair crews arrived early the next morning.",clip:1},"wh-occurred":{src:"concept:82:words:1:hook",route:"#/word/occurred",cta:"Open the word card",title:"Remember it · occurred",body:"It OCCURRed to me: double 'c', double 'r' — two pairs, like two things running into each other."},"wd-beginning":{src:"concept:82:words:2:def",route:"#/word/beginning",cta:"Open the word card",title:"beginning",roman:"bih-GIH-nihng",body:"the event consisting of the start of something",clip:1},"wx-beginning":{src:"concept:82:words:2:ex",route:"#/word/beginning",cta:"Open the word card",title:"In a sentence · beginning",body:"the beginning of the war",clip:1},"wh-beginning":{src:"concept:82:words:2:hook",route:"#/word/beginning",cta:"Open the word card",title:"Remember it · beginning",body:"Beginning has two n's — you need two feet to take your first step."},"wd-preferred":{src:"concept:82:words:3:def",route:"#/word/preferred",cta:"Open the word card",title:"preferred",roman:"pruh-FURD",body:"like better; value more highly",clip:1},"wx-preferred":{src:"concept:82:words:3:ex",route:"#/word/preferred",cta:"Open the word card",title:"In a sentence · preferred",body:"Maya preferred the quiet library corner to the noisy cafeteria whenever lunchtime came around.",clip:1},"wh-preferred":{src:"concept:82:words:3:hook",route:"#/word/preferred",cta:"Open the word card",title:"Remember it · preferred",body:"PREFERRED doubles the R because the stress falls on -FER — you really, REALLY prefer it, so add an extra R."},"wd-controlled":{src:"concept:82:words:4:def",route:"#/word/controlled",cta:"Open the word card",title:"controlled",roman:"kuh-NTROHLD",body:"exercise authoritative control or power over",clip:1},"wx-controlled":{src:"concept:82:words:4:ex",route:"#/word/controlled",cta:"Open the word card",title:"In a sentence · controlled",body:"The experienced pilot controlled the small aircraft smoothly through the sudden turbulence, keeping the passengers calm by maintaining a steady altitude and speaking reassuringly over the intercom throughout the bumpy flight.",clip:1},"wh-controlled":{src:"concept:82:words:4:hook",route:"#/word/controlled",cta:"Open the word card",title:"Remember it · controlled",body:"CONTROLLED doubles the L — it takes two strong Ls to hold everything under control."},"wo-controlled":{src:"lore:controlled:0",route:"#/word/controlled",cta:"Open the word card",title:"Where it comes from · controlled",body:"Medieval Latin contrarotulus = counter-roll"},"wd-traveled":{src:"concept:82:words:5:def",route:"#/word/traveled",cta:"Open the word card",title:"traveled",roman:"TRA-vuhld",body:"change location; move, travel, or proceed, also metaphorically",clip:1},"wx-traveled":{src:"concept:82:words:5:ex",route:"#/word/traveled",cta:"Open the word card",title:"In a sentence · traveled",body:"Our class traveled by train to the coast to study crabs in the tide pools.",clip:1},"wh-traveled":{src:"concept:82:words:5:hook",route:"#/word/traveled",cta:"Open the word card",title:"Remember it · traveled",body:"American TRAVELED uses one L — one L for one continent crossed."},"wd-canceled":{src:"concept:82:words:6:def",route:"#/word/canceled",cta:"Open the word card",title:"canceled",roman:"KA-nsuhld",body:"postpone indefinitely or annul something that was scheduled",clip:1},"wx-canceled":{src:"concept:82:words:6:ex",route:"#/word/canceled",cta:"Open the word card",title:"In a sentence · canceled",body:"Heavy snow canceled the football match, so we played board games in the hall instead.",clip:1},"wh-canceled":{src:"concept:82:words:6:hook",route:"#/word/canceled",cta:"Open the word card",title:"Remember it · canceled",body:"In American English, one L is CANCELED — the second L got crossed out, just like the event!"},"wd-accommodate":{src:"concept:82:words:7:def",route:"#/word/accommodate",cta:"Open the word card",title:"accommodate",roman:"uh-k-AH-m-uh-d-ay-t",body:"is to do a kindness or a favor to oblige",clip:1},"wx-accommodate":{src:"concept:82:words:7:ex",route:"#/word/accommodate",cta:"Open the word card",title:"In a sentence · accommodate",body:"The hotel staff worked hard to accommodate every guest's special request, arranging extra pillows, dietary meals, and late checkout times to ensure that everyone left feeling comfortable and well cared for.",clip:1},"wh-accommodate":{src:"concept:82:words:7:hook",route:"#/word/accommodate",cta:"Open the word card",title:"Remember it · accommodate",body:"ACCOMModate needs double C and double M — it takes TWO of each to fit everyone in."},"wo-accommodate":{src:"lore:accommodate:0",route:"#/word/accommodate",cta:"Open the word card",title:"Where it comes from · accommodate",body:"Latin accommodare = to make fit, from ad+commodus = fitting"},"wd-embarrass":{src:"concept:82:words:8:def",route:"#/word/embarrass",cta:"Open the word card",title:"embarrass",roman:"ih-m-b-EH-r-uh-s",body:"is to cause confusion and shame to",clip:1},"wx-embarrass":{src:"concept:82:words:8:ex",route:"#/word/embarrass",cta:"Open the word card",title:"In a sentence · embarrass",body:"Forgetting my lines on stage did embarrass me, and my cheeks turned bright red.",clip:1},"wh-embarrass":{src:"concept:82:words:8:hook",route:"#/word/embarrass",cta:"Open the word card",title:"Remember it · embarrass",body:"I'm Really Really Awkward — embaRRASS has a double R and double S to make you squirm."},"wo-embarrass":{src:"lore:embarrass:0",route:"#/word/embarrass",cta:"Open the word card",title:"Where it comes from · embarrass",body:"French embarrasser = to block/impede"},"wd-millennium":{src:"concept:82:words:9:def",route:"#/word/millennium",cta:"Open the word card",title:"millennium",roman:"m-uh-l-EH-n-ee-uh-m",body:"is a period of 1000 years",clip:1},"wx-millennium":{src:"concept:82:words:9:ex",route:"#/word/millennium",cta:"Open the word card",title:"In a sentence · millennium",body:"Scientists predicted it would take a millennium for the ancient forest to fully recover from the fire.",clip:1},"wh-millennium":{src:"concept:82:words:9:hook",route:"#/word/millennium",cta:"Open the word card",title:"Remember it · millennium",body:"MILLENNIUM: double L, double N, -ium at the end—two pairs for two thousand years of confusion."},"wo-millennium":{src:"lore:millennium:0",route:"#/word/millennium",cta:"Open the word card",title:"Where it comes from · millennium",body:"Latin mille = thousand + annus = year"},"wd-necessary":{src:"concept:82:words:10:def",route:"#/word/necessary",cta:"Open the word card",title:"necessary",roman:"n-EH-s-uh-s-eh-r-ee",body:"is being essential indispensable",clip:1},"wx-necessary":{src:"concept:82:words:10:ex",route:"#/word/necessary",cta:"Open the word card",title:"In a sentence · necessary",body:"Warm boots are necessary if you plan to hike through the snowy woods tomorrow.",clip:1},"wh-necessary":{src:"concept:82:words:10:hook",route:"#/word/necessary",cta:"Open the word card",title:"Remember it · necessary",body:"NECESSARY: one Collar, two Socks — one 'c' and two 's's, like a shirt needs."},"wo-necessary":{src:"lore:necessary:0",route:"#/word/necessary",cta:"Open the word card",title:"Where it comes from · necessary",body:"Latin necesse = unavoidable, needful"},"wd-occasion":{src:"concept:82:words:11:def",route:"#/word/occasion",cta:"Open the word card",title:"occasion",roman:"uh-KAY-zhuhn",body:"a special event, or a particular time when something happens",clip:1},"wx-occasion":{src:"concept:82:words:11:ex",route:"#/word/occasion",cta:"Open the word card",title:"In a sentence · occasion",body:"Grandma's ninetieth birthday was a grand occasion, with cousins arriving from three different countries.",clip:1},"wh-occasion":{src:"concept:82:words:11:hook",route:"#/word/occasion",cta:"Open the word card",title:"Remember it · occasion",body:"One Collar, one Suitcase: oc-ca-sion — double C, single S, for a special event."},"wo-occasion":{src:"lore:occasion:0",route:"#/word/occasion",cta:"Open the word card",title:"Where it comes from · occasion",body:"Latin occasio = opportunity, from occidere = to fall down"},"wd-recommend":{src:"concept:82:words:12:def",route:"#/word/recommend",cta:"Open the word card",title:"recommend",roman:"r-eh-k-uh-m-EH-n-d",body:"is to present as worthy of confidence or acceptance",clip:1},"wx-recommend":{src:"concept:82:words:12:ex",route:"#/word/recommend",cta:"Open the word card",title:"In a sentence · recommend",body:"The travel agent recommended strongly that we not travel on Thanksgiving Day",clip:1},"wh-recommend":{src:"concept:82:words:12:hook",route:"#/word/recommend",cta:"Open the word card",title:"Remember it · recommend",body:"RECOMMEND has one 'c' and two 'm's — think: I'd COMMEND it again, so one 'c', double 'm'."},"wo-recommend":{src:"lore:recommend:0",route:"#/word/recommend",cta:"Open the word card",title:"Where it comes from · recommend",body:"Latin commendare = to entrust, praise"},"wd-satellite":{src:"concept:82:words:13:def",route:"#/word/satellite",cta:"Open the word card",title:"satellite",roman:"s-A-t-uh-l-ay-t",body:"a man-made object placed in orbit around the Earth or another celestial body to collect data or aid communication",clip:1},"wx-satellite":{src:"concept:82:words:13:ex",route:"#/word/satellite",cta:"Open the word card",title:"In a sentence · satellite",body:"a city and its satellite communities",clip:1},"wh-satellite":{src:"concept:82:words:13:hook",route:"#/word/satellite",cta:"Open the word card",title:"Remember it · satellite",body:"SATellite has one T then double L — it SITS in orbit like a steady attendant"},"wo-satellite":{src:"lore:satellite:0",route:"#/word/satellite",cta:"Open the word card",title:"Where it comes from · satellite",body:"Latin satelles = attendant, escort, guard"},"wd-parallel":{src:"concept:82:words:14:def",route:"#/word/parallel",cta:"Open the word card",title:"parallel",roman:"p-EH-r-uh-l-eh-l",body:"is extending in the same direction but never converging",clip:1},"wx-parallel":{src:"concept:82:words:14:ex",route:"#/word/parallel",cta:"Open the word card",title:"In a sentence · parallel",body:"parallels never meet",clip:1},"wh-parallel":{src:"concept:82:words:14:hook",route:"#/word/parallel",cta:"Open the word card",title:"Remember it · parallel",body:"PARALLEL has two L's in the middle and two L's at the end — like two parallel lines running side by side: para-L-L-e-L-L."},"wo-parallel":{src:"lore:parallel:0",route:"#/word/parallel",cta:"Open the word card",title:"Where it comes from · parallel",body:"Greek parallēlos = beside one another"},"wd-committee":{src:"concept:82:words:15:def",route:"#/word/committee",cta:"Open the word card",title:"committee",roman:"kuh-MIH-tee",body:"a special group delegated to consider some matter;  - Milton Berle",clip:1},"wx-committee":{src:"concept:82:words:15:ex",route:"#/word/committee",cta:"Open the word card",title:"In a sentence · committee",body:"a committee is a group that keeps minutes and loses hours",clip:1},"wh-committee":{src:"concept:82:words:15:hook",route:"#/word/committee",cta:"Open the word card",title:"Remember it · committee",body:"A comMITTEE has double M, double T, double E — three pairs, like three pairs of people on the committee!"},"wo-committee":{src:"lore:committee:0",route:"#/word/committee",cta:"Open the word card",title:"Where it comes from · committee",body:"Latin committere = to entrust, com- + mittere = to send"},"li-u16":{src:"concept:83:concept",route:"#/stop/u16",cta:"Open this stop",title:"c = /s/ Before e / i / y",body:"The letter c has two sounds: /k/ (hard) before a, o, u, and /s/ (soft) before e, i, y. Knowing this rule explains dozens of spelling patterns and helps decode words you've never seen."},"lc-u16-0":{src:"concept:83:cards:0",route:"#/stop/u16",cta:"Open this stop",title:"c = /s/ Before e / i / y · The Rule",body:"c = /k/ before a, o, u, and consonants: cat, cold, cup, craft. c = /s/ before e, i, y: ceiling, city, cycle. This explains why cell starts with /s/ and call starts with /k/ — same letter, different vowel following it."},"lc-u16-1":{src:"concept:83:cards:1",route:"#/stop/u16",cta:"Open this stop",title:"c = /s/ Before e / i / y · -sc- = /s/ Before e/i",body:"The cluster -sc- before e or i also = /s/: iridescent (sc + e = /s/), adolescent, luminescent, quiescent, convalescent, effervescent, incandescent. The s in -sc- is redundant to the /s/ sound of c — but both letters must be spelled."},"lc-u16-2":{src:"concept:83:cards:2",route:"#/stop/u16",cta:"Open this stop",title:"c = /s/ Before e / i / y · -ce and -ci- Inside Words",body:"Susceptible (sus- + cep- + -ible) — the c before e → susceptible not susceptable. Conceit (con- + ceit) — c before e. Luscious — c before i. Precious — c before i. Spacious — c before i. Recognizing -ci- as /sh/ in suffixes like -cious, -cial, -cient is a major spelling pattern."},"lc-u16-3":{src:"concept:83:cards:3",route:"#/stop/u16",cta:"Open this stop",title:"c = /s/ Before e / i / y · Acquiesce — the c/qu Combination",body:"Acquiesce (ac- + quiescere = rest) — the qu keeps its /kw/ sound; the -esce has c before e = /s/. The word has two different c sounds: /kw/ (in qu) and /s/ (in -sc-). Spelling: A-C-Q-U-I-E-S-C-E."},"lc-u16-4":{src:"concept:83:cards:4",route:"#/stop/u16",cta:"Open this stop",title:"c = /s/ Before e / i / y · Soft c vs Hard c in the Same Word",body:"Circle = cir (soft c before i) + -cle (hard c before l). Circus = cir (soft c before i) + -cus (hard c before u). Concede = con (hard c) + -cede (soft c before e). The position of the vowel following the c tells you which sound it makes — every time."},"uq-u16-0":{src:"unit:u16:qs:0",route:"#/stop/u16",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “c = /s/ Before e / i / y”?",opts:["The letter c has two sounds: /k/ (hard) before a, o, u, and /s/ (soft) before e, i, y.","Latin ex- = out of.","Latin inter- = between two or more things.","These noun suffixes create abstract nouns from adjectives."],after:"From “c = /s/ Before e / i / y”."}},"uq-u16-3":{src:"unit:u16:qs:3",route:"#/stop/u16",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁ — one R, like a single rainbow arc over the word.” — which word is this hook about?",opts:["iridescent","adolescent","luminescent","quiescent"],after:"From “c = /s/ Before e / i / y”."}},"wd-iridescent":{src:"concept:83:words:0:def",route:"#/word/iridescent",cta:"Open the word card",title:"iridescent",roman:"ih-r-uh-d-EH-s-uh-n-t",body:"is displaying a play of bright colors like a rainbow",clip:1},"wx-iridescent":{src:"concept:83:words:0:ex",route:"#/word/iridescent",cta:"Open the word card",title:"In a sentence · iridescent",body:"The hummingbird hovered just inches from the flower, its iridescent throat feathers shifting from deep emerald to brilliant violet as it tilted its tiny head, catching the afternoon sunlight at a slightly different angle.",clip:1},"wh-iridescent":{src:"concept:83:words:0:hook",route:"#/word/iridescent",cta:"Open the word card",title:"Remember it · iridescent",body:"Iridescent — one R, like a single rainbow arc over the word."},"wo-iridescent":{src:"lore:iridescent:0",route:"#/word/iridescent",cta:"Open the word card",title:"Where it comes from · iridescent",body:"Greek iris = rainbow + Latin -escent(becoming)"},"wd-adolescent":{src:"concept:83:words:1:def",route:"#/word/adolescent",cta:"Open the word card",title:"adolescent",roman:"a-duh-LEH-suhnt",body:"a juvenile between the onset of puberty and maturity",clip:1},"wx-adolescent":{src:"concept:83:words:1:ex",route:"#/word/adolescent",cta:"Open the word card",title:"In a sentence · adolescent",body:"As an adolescent, Theo struggled to balance the pressures of middle school friendships, growing responsibilities at home, and his own rapidly changing feelings about who he wanted to become.",clip:1},"wh-adolescent":{src:"concept:83:words:1:hook",route:"#/word/adolescent",cta:"Open the word card",title:"Remember it · adolescent",body:"An ADOLESCENT grows — spell the SCENT of growth: a-d-o-l-e-S-C-E-N-T."},"wo-adolescent":{src:"lore:adolescent:0",route:"#/word/adolescent",cta:"Open the word card",title:"Where it comes from · adolescent",body:"Latin adolescere = to grow up"},"wd-luminescent":{src:"concept:83:words:2:def",route:"#/word/luminescent",cta:"Open the word card",title:"luminescent",roman:"loo-muh-NEH-suhnt",body:"emitting light not caused by heat",clip:1},"wx-luminescent":{src:"concept:83:words:2:ex",route:"#/word/luminescent",cta:"Open the word card",title:"In a sentence · luminescent",body:"The luminescent stickers on her ceiling glowed softly after the lights went out.",clip:1},"wh-luminescent":{src:"concept:83:words:2:hook",route:"#/word/luminescent",cta:"Open the word card",title:"Remember it · luminescent",body:"LUMINESCENT ends in '-ent' like a glowing agent — only an '-ent' student spells it right."},"wo-luminescent":{src:"lore:luminescent:0",route:"#/word/luminescent",cta:"Open the word card",title:"Where it comes from · luminescent",body:"Latin lumen = light + -escent = becoming"},"wd-quiescent":{src:"concept:83:words:3:def",route:"#/word/quiescent",cta:"Open the word card",title:"quiescent",roman:"k-w-ay-EH-s-uh-n-t",body:"is being at rest quiet inactive",clip:1},"wx-quiescent":{src:"concept:83:words:3:ex",route:"#/word/quiescent",cta:"Open the word card",title:"In a sentence · quiescent",body:"the quiescent level of centimeter wave-length solar radiation",clip:1},"wh-quiescent":{src:"concept:83:words:3:hook",route:"#/word/quiescent",cta:"Open the word card",title:"Remember it · quiescent",body:"QUIESCENT ends in -SCENT: imagine a quiet, still room with a faint scent — perfectly at rest."},"wo-quiescent":{src:"lore:quiescent:0",route:"#/word/quiescent",cta:"Open the word card",title:"Where it comes from · quiescent",body:"Latin quiescens = resting, from quiescere = to rest"},"wd-effervescent":{src:"concept:83:words:4:def",route:"#/word/effervescent",cta:"Open the word card",title:"effervescent",roman:"eh-f-ur-v-EH-s-uh-n-t",body:"used of wines and waters; charged naturally or artificially with carbon dioxide",clip:1},"wx-effervescent":{src:"concept:83:words:4:ex",route:"#/word/effervescent",cta:"Open the word card",title:"In a sentence · effervescent",body:"The effervescent new student bubbled with energy from the very first day, cracking jokes, complimenting everyone's artwork, and making the entire classroom feel lighter and more fun simply by walking through the door each morning.",clip:1},"wh-effervescent":{src:"concept:83:words:4:hook",route:"#/word/effervescent",cta:"Open the word card",title:"Remember it · effervescent",body:"EFFERVescent = bubbles FERVOR-ing out — think of a soda bottle fizzing over."},"wo-effervescent":{src:"lore:effervescent:0",route:"#/word/effervescent",cta:"Open the word card",title:"Where it comes from · effervescent",body:"Latin effervescere = to boil up, from ex-(out)+fervere = to boil"},"wd-incandescent":{src:"concept:83:words:5:def",route:"#/word/incandescent",cta:"Open the word card",title:"incandescent",roman:"ih-n-k-uh-n-d-EH-s-uh-n-t",body:"strikingly bright radiant or clear",clip:1},"wx-incandescent":{src:"concept:83:words:5:ex",route:"#/word/incandescent",cta:"Open the word card",title:"In a sentence · incandescent",body:"an incandescent bulb",clip:1},"wh-incandescent":{src:"concept:83:words:5:hook",route:"#/word/incandescent",cta:"Open the word card",title:"Remember it · incandescent",body:"An incanDESCENT bulb glows as it DESCENDS into heat — spell the SCENT of hot wax: -s-c-e-n-t."},"wo-incandescent":{src:"lore:incandescent:0",route:"#/word/incandescent",cta:"Open the word card",title:"Where it comes from · incandescent",body:"Latin incandescere = to glow white-hot, from candere = to shine"},"wd-luscious":{src:"concept:83:words:6:def",route:"#/word/luscious",cta:"Open the word card",title:"luscious",roman:"l-UH-sh-ih-s",body:"is highly pleasing to the taste or smell",clip:1},"wx-luscious":{src:"concept:83:words:6:ex",route:"#/word/luscious",cta:"Open the word card",title:"In a sentence · luscious",body:"The baker arranged a luscious display of ripe strawberries, glazed pastries, and cream-filled tarts that made every customer stop and stare hungrily through the window.",clip:1},"wh-luscious":{src:"concept:83:words:6:hook",route:"#/word/luscious",cta:"Open the word card",title:"Remember it · luscious",body:"LUSCIOUS has no H—it's lus-CIOUS, like delicious without the deli, packed with flavor."},"wo-luscious":{src:"lore:luscious:0",route:"#/word/luscious",cta:"Open the word card",title:"Where it comes from · luscious",body:"Latin luxuriosus = luxuriant, altered form"},"wd-precious":{src:"concept:83:words:7:def",route:"#/word/precious",cta:"Open the word card",title:"precious",roman:"p-r-EH-sh-uh-s",body:"is of high price or great value",clip:1},"wx-precious":{src:"concept:83:words:7:ex",route:"#/word/precious",cta:"Open the word card",title:"In a sentence · precious",body:"The locket passed down through four generations was precious not because of its gold casing but because of the tiny photographs it held inside.",clip:1},"wh-precious":{src:"concept:83:words:7:hook",route:"#/word/precious",cta:"Open the word card",title:"Remember it · precious",body:"PRECIOUS gems have a PRICE — preci+ous, don't drop the 'i' that spells 'pricei' inside."},"wo-precious":{src:"lore:precious:0",route:"#/word/precious",cta:"Open the word card",title:"Where it comes from · precious",body:"Latin 'pretiosus' = of great value, from 'pretium' = price"},"wd-spacious":{src:"concept:83:words:8:def",route:"#/word/spacious",cta:"Open the word card",title:"spacious",roman:"s-p-AY-sh-uh-s",body:"affording much room not narrow or constricted roomy",clip:1},"wx-spacious":{src:"concept:83:words:8:ex",route:"#/word/spacious",cta:"Open the word card",title:"In a sentence · spacious",body:"After years of sharing a tiny bedroom with two siblings, moving into a spacious room with her own desk, bookshelf, and window seat felt like an absolute luxury to Maya.",clip:1},"wh-spacious":{src:"concept:83:words:8:hook",route:"#/word/spacious",cta:"Open the word card",title:"Remember it · spacious",body:"A SPACIOUS room has SPACE — keep the I before OUS: spac-I-ous, because you need an 'I' to see all that space."},"wo-spacious":{src:"lore:spacious:0",route:"#/word/spacious",cta:"Open the word card",title:"Where it comes from · spacious",body:"Latin spatium = space, area"},"wd-susceptible":{src:"concept:83:words:9:def",route:"#/word/susceptible",cta:"Open the word card",title:"susceptible",roman:"suh-SEH-ptuh-buhl",body:"(often followed by `of' or `to') yielding readily to or capable of",clip:1},"wx-susceptible":{src:"concept:83:words:9:ex",route:"#/word/susceptible",cta:"Open the word card",title:"In a sentence · susceptible",body:"susceptible to colds",clip:1},"wh-susceptible":{src:"concept:83:words:9:hook",route:"#/word/susceptible",cta:"Open the word card",title:"Remember it · susceptible",body:"susceptIBLE — end in -ible not -able; think 'I'll Be LEt in easily' — I-B-L-E for things easily taken up."},"wo-susceptible":{src:"lore:susceptible:0",route:"#/word/susceptible",cta:"Open the word card",title:"Where it comes from · susceptible",body:"Latin suscipere = to take up, susceptus = taken up"},"wd-acquiesce":{src:"concept:83:words:10:def",route:"#/word/acquiesce",cta:"Open the word card",title:"acquiesce",roman:"a-kwee-EHS",body:"to agree or express agreement",clip:1},"wx-acquiesce":{src:"concept:83:words:10:ex",route:"#/word/acquiesce",cta:"Open the word card",title:"In a sentence · acquiesce",body:"After hours of debate, Marcus finally decided to acquiesce to his teammates' plan even though he still had doubts about it.",clip:1},"wh-acquiesce":{src:"concept:83:words:10:hook",route:"#/word/acquiesce",cta:"Open the word card",title:"Remember it · acquiesce",body:"ACQUIesce — QUIET agreement; when you acquiesce, you quietly give in"},"wo-acquiesce":{src:"lore:acquiesce:0",route:"#/word/acquiesce",cta:"Open the word card",title:"Where it comes from · acquiesce",body:"Latin 'acquiescere' = to rest in, from 'ad-' = to + 'quiescere' = to be quiet, rest"},"wd-conceit":{src:"concept:83:words:11:def",route:"#/word/conceit",cta:"Open the word card",title:"conceit",roman:"k-uh-n-s-EE-t",body:"is an excessively favorable opinion of oneself",clip:1},"wx-conceit":{src:"concept:83:words:11:ex",route:"#/word/conceit",cta:"Open the word card",title:"In a sentence · conceit",body:"he could always come up with some inspired off-the-wall conceit",clip:1},"wh-conceit":{src:"concept:83:words:11:hook",route:"#/word/conceit",cta:"Open the word card",title:"Remember it · conceit",body:"conCEIT — someone full of conceit thinks they're the ELITE"},"wo-conceit":{src:"lore:conceit:0",route:"#/word/conceit",cta:"Open the word card",title:"Where it comes from · conceit",body:"Latin concipere = to conceive, take in, from con-(together)+capere(to take)"},"wd-scintillating":{src:"concept:83:words:12:def",route:"#/word/scintillating",cta:"Open the word card",title:"scintillating",roman:"SIN-tih-lay-ting",body:"Brilliantly clever, lively, and stimulating; sparkling with wit, energy, or dazzling light.",clip:1},"wx-scintillating":{src:"concept:83:words:12:ex",route:"#/word/scintillating",cta:"Open the word card",title:"In a sentence · scintillating",body:"the substance scintillated sparks and flashes",clip:1},"wh-scintillating":{src:"concept:83:words:12:hook",route:"#/word/scintillating",cta:"Open the word card",title:"Remember it · scintillating",body:"SCINTILLATING has TILLA inside — imagine a caterpillar named TILLA who sparkles and glitters as she walks."},"wd-nascent":{src:"concept:83:words:13:def",route:"#/word/nascent",cta:"Open the word card",title:"nascent",roman:"n-AY-s-uh-n-t",body:"is beginning to exist or develop",clip:1},"wx-nascent":{src:"concept:83:words:13:ex",route:"#/word/nascent",cta:"Open the word card",title:"In a sentence · nascent",body:"The nascent robotics club at Jefferson Middle School had only four members and one broken motor, but their enthusiasm and creativity suggested something truly exciting was just beginning to take shape.",clip:1},"wh-nascent":{src:"concept:83:words:13:hook",route:"#/word/nascent",cta:"Open the word card",title:"Remember it · nascent",body:"NASCent — NASCar is a newly born racing sport; things that are NASC-ent are just being born"},"wo-nascent":{src:"lore:nascent:0",route:"#/word/nascent",cta:"Open the word card",title:"Where it comes from · nascent",body:"Latin nasci = to be born"},"wd-obsolescent":{src:"concept:83:words:14:def",route:"#/word/obsolescent",cta:"Open the word card",title:"obsolescent",roman:"ah-b-s-uh-l-EH-s-uh-n-t",body:"means passing out of use as a word",clip:1},"wx-obsolescent":{src:"concept:83:words:14:ex",route:"#/word/obsolescent",cta:"Open the word card",title:"In a sentence · obsolescent",body:"With smartphones everywhere, the pay phone has become an obsolescent relic of a previous generation.",clip:1},"wh-obsolescent":{src:"concept:83:words:14:hook",route:"#/word/obsolescent",cta:"Open the word card",title:"Remember it · obsolescent",body:"An obsoleSCENT thing is fading from the SCENE — keep the S-C in the middle!"},"wo-obsolescent":{src:"lore:obsolescent:0",route:"#/word/obsolescent",cta:"Open the word card",title:"Where it comes from · obsolescent",body:"Latin obsolescere = to fall into disuse"},"li-u17":{src:"concept:84:concept",route:"#/stop/u17",cta:"Open this stop",title:"ph = /f/ Sound (Greek Signal)",body:"ph = /f/ is the most reliable Greek origin signal in English. It appears ONLY in Greek-origin words (or words modeled on Greek). Hearing /f/ in a learned, scientific, or literary word = look for ph, not f."},"lc-u17-0":{src:"concept:84:cards:0",route:"#/stop/u17",cta:"Open this stop",title:"ph = /f/ Sound (Greek Signal) · The Golden Rule",body:"If you hear /f/ in a learned, scientific, or literary word — write ph not f. Phenomenon, ephemeral, diphtheria, phosphorus, sycophant, sophistry, metaphor, diaphanous, asphyxia, phlegm. The ph is Greek phi (φ), and it entered English with the Greek vocabulary."},"lc-u17-1":{src:"concept:84:cards:1",route:"#/stop/u17",cta:"Open this stop",title:"ph = /f/ Sound (Greek Signal) · The Exception",body:"Common everyday English words use f not ph: fun, fish, finger, fly, fog, flat. The rule only applies to borrowed learned words. Fahrenheit = German, uses f. Fan = Old English, uses f. If it is a short, everyday word you knew as a child → probably f."},"lc-u17-2":{src:"concept:84:cards:2",route:"#/stop/u17",cta:"Open this stop",title:"ph = /f/ Sound (Greek Signal) · ph in the Middle of Words",body:"Elephant (elephas = Greek) — ph in the middle. Orphan (orphanos = Greek) — ph in the middle. Emphasis (emphasis = Greek) — ph in the middle. Amphitheater — ph inside. Epiphany — ph inside. Morphine — ph inside. The ph appears anywhere in the word, not just at the start."},"lc-u17-3":{src:"concept:84:cards:3",route:"#/stop/u17",cta:"Open this stop",title:"ph = /f/ Sound (Greek Signal) · The Hardest ph Clusters",body:"Diphthong = di- + phthongos = two sounds merged — has -phth- cluster (two silent-seeming letters working together). Ophthalmology = -phth- cluster inside. Phthisis (tuberculosis) starts with pht- — P-H-T-H-I-S-I-S. These are the most extreme Greek ph spellings."},"lc-u17-4":{src:"concept:84:cards:4",route:"#/stop/u17",cta:"Open this stop",title:"ph = /f/ Sound (Greek Signal) · Building ph Word Families",body:"-phage (eating): sarcophagus (flesh eater). -phor (carrying): metaphor, phosphor. -phyte (plant): lithophyte, epiphyte. -phon (sound): microphone, saxophone. -phil (loving): bibliophile, anglophile. One pattern — the ph — unlocks them all."},"uq-u17-0":{src:"unit:u17:qs:0",route:"#/stop/u17",cta:"Open this stop",title:"The big idea",play:{q:"Which of these is the big idea of “ph = /f/ Sound (Greek Signal)”?",opts:["ph = /f/ is the most reliable Greek origin signal in English.","Latin ex- = out of.","Latin inter- = between two or more things.","These noun suffixes create abstract nouns from adjectives."],after:"From “ph = /f/ Sound (Greek Signal)”."}},"uq-u17-3":{src:"unit:u17:qs:3",route:"#/stop/u17",cta:"Open this stop",title:"Whose hook?",play:{q:"“▁▁▁ fabric is so sheer you could see a DIAMOND through it.” — which word is this hook about?",opts:["diaphanous","phenomenon","ephemeral","sycophant"],after:"From “ph = /f/ Sound (Greek Signal)”."}},"wd-diaphanous":{src:"concept:84:words:0:def",route:"#/word/diaphanous",cta:"Open the word card",title:"diaphanous",roman:"d-ay-A-f-uh-n-ih-s",body:"means very sheer and light",clip:1},"wx-diaphanous":{src:"concept:84:words:0:ex",route:"#/word/diaphanous",cta:"Open the word card",title:"In a sentence · diaphanous",body:"a hat with a diaphanous veil",clip:1},"wh-diaphanous":{src:"concept:84:words:0:hook",route:"#/word/diaphanous",cta:"Open the word card",title:"Remember it · diaphanous",body:"DIAphanous fabric is so sheer you could see a DIAMOND through it."},"wo-diaphanous":{src:"lore:diaphanous:0",route:"#/word/diaphanous",cta:"Open the word card",title:"Where it comes from · diaphanous",body:"Greek diaphainein = to show through"},"wd-phenomenon":{src:"concept:84:words:1:def",route:"#/word/phenomenon",cta:"Open the word card",title:"phenomenon",roman:"f-uh-n-AH-m-uh-n-ah-n",body:"is a fact or occurrence observed or observable",clip:1},"wx-phenomenon":{src:"concept:84:words:1:ex",route:"#/word/phenomenon",cta:"Open the word card",title:"In a sentence · phenomenon",body:"The sudden appearance of the northern lights over the city was a spectacular natural phenomenon.",clip:1},"wh-phenomenon":{src:"concept:84:words:1:hook",route:"#/word/phenomenon",cta:"Open the word card",title:"Remember it · phenomenon",body:"PHENOMENON ends in -ON not -IN — one phENOMENon, many phenomENA."},"wo-phenomenon":{src:"lore:phenomenon:0",route:"#/word/phenomenon",cta:"Open the word card",title:"Where it comes from · phenomenon",body:"Greek phainomenon = that which appears"},"wd-ephemeral":{src:"concept:84:words:2:def",route:"#/word/ephemeral",cta:"Open the word card",title:"ephemeral",roman:"ih-f-EH-m-ur-uh-l",body:"is lasting a very short time",clip:1},"wx-ephemeral":{src:"concept:84:words:2:ex",route:"#/word/ephemeral",cta:"Open the word card",title:"In a sentence · ephemeral",body:"the ephemeral joys of childhood",clip:1},"wh-ephemeral":{src:"concept:84:words:2:hook",route:"#/word/ephemeral",cta:"Open the word card",title:"Remember it · ephemeral",body:"EPHEMERAL: 'Every Petal Has Every Morning Erased, Really A Loss' — beauty gone by dawn."},"wo-ephemeral":{src:"lore:ephemeral:0",route:"#/word/ephemeral",cta:"Open the word card",title:"Where it comes from · ephemeral",body:"Greek ephemeros = lasting a day, from epi (on) + hemera (day)"},"wd-sycophant":{src:"concept:84:words:3:def",route:"#/word/sycophant",cta:"Open the word card",title:"sycophant",roman:"SIK-uh-fant",body:"a person who tries to please someone in order to gain a personal advantage",clip:1},"wx-sycophant":{src:"concept:84:words:3:ex",route:"#/word/sycophant",cta:"Open the word card",title:"In a sentence · sycophant",body:"The new employee was such a sycophant that he laughed loudly at every one of the boss's jokes, no matter how unfunny.",clip:1},"wh-sycophant":{src:"concept:84:words:3:hook",route:"#/word/sycophant",cta:"Open the word card",title:"Remember it · sycophant",body:"A SYCOphant is SICK with flattery to get what they want"},"wo-sycophant":{src:"lore:sycophant:0",route:"#/word/sycophant",cta:"Open the word card",title:"Where it comes from · sycophant",body:"Greek sykophantes = informer, from sykon (fig) + phainein (to show)"},"wd-metaphor":{src:"concept:84:words:4:def",route:"#/word/metaphor",cta:"Open the word card",title:"metaphor",roman:"m-EH-t-uh-f-aw-r",body:"is a figure of speech in which a term is applied to something to which it isn't literally applicable",clip:1},"wx-metaphor":{src:"concept:84:words:4:ex",route:"#/word/metaphor",cta:"Open the word card",title:"In a sentence · metaphor",body:"When the poet wrote that life is a rollercoaster, she was using a metaphor to describe its unpredictable ups and downs.",clip:1},"wh-metaphor":{src:"concept:84:words:4:hook",route:"#/word/metaphor",cta:"Open the word card",title:"Remember it · metaphor",body:"A metaPHOR carries meaning across — it PHORwarded an idea to a new place."},"wo-metaphor":{src:"lore:metaphor:0",route:"#/word/metaphor",cta:"Open the word card",title:"Where it comes from · metaphor",body:"Greek meta = over + pherein = to carry"},"wd-asphyxia":{src:"concept:84:words:5:def",route:"#/word/asphyxia",cta:"Open the word card",title:"asphyxia",roman:"as-FIK-see-uh",body:"a condition in which insufficient or no oxygen and carbon dioxide are exchanged on a ventilatory basis; caused by choking or drowning or electric shock or poison gas",clip:1},"wx-asphyxia":{src:"concept:84:words:5:ex",route:"#/word/asphyxia",cta:"Open the word card",title:"In a sentence · asphyxia",body:"The doctor explained that asphyxia occurs when the body is deprived of the oxygen it needs to survive.",clip:1},"wh-asphyxia":{src:"concept:84:words:5:hook",route:"#/word/asphyxia",cta:"Open the word card",title:"Remember it · asphyxia",body:"ASPHYXIA has a Y after SPH — you gasp 'WHY?' when you can't breathe, and Y is right there in the middle."},"wo-asphyxia":{src:"lore:asphyxia:0",route:"#/word/asphyxia",cta:"Open the word card",title:"Where it comes from · asphyxia",body:"Greek a- = not + sphyzein = to throb/pulse"},"wd-phlegm":{src:"concept:84:words:6:def",route:"#/word/phlegm",cta:"Open the word card",title:"phlegm",roman:"FLEHM",body:"thick sticky mucus made in the nose and throat, especially during a cold",clip:1},"wx-phlegm":{src:"concept:84:words:6:ex",route:"#/word/phlegm",cta:"Open the word card",title:"In a sentence · phlegm",body:"A nasty cold left Ravi coughing up phlegm and sipping honey tea all week.",clip:1},"wh-phlegm":{src:"concept:84:words:6:hook",route:"#/word/phlegm",cta:"Open the word card",title:"Remember it · phlegm",body:"PHLEGM hides a silent G — the G gets stuck in your throat just like phlegm does."},"wd-diphthong":{src:"concept:84:words:7:def",route:"#/word/diphthong",cta:"Open the word card",title:"diphthong",roman:"d-IH-p-th-aw-ng",body:"is an unsegmented gliding speech sound",clip:1},"wx-diphthong":{src:"concept:84:words:7:ex",route:"#/word/diphthong",cta:"Open the word card",title:"In a sentence · diphthong",body:"The speech teacher explained that the word 'coin' contains a diphthong because two vowel sounds blend together smoothly.",clip:1},"wh-diphthong":{src:"concept:84:words:7:hook",route:"#/word/diphthong",cta:"Open the word card",title:"Remember it · diphthong",body:"A DIPHTHONG has TWO sounds — and two silent letters ph and th, making it doubly tricky."},"wo-diphthong":{src:"lore:diphthong:0",route:"#/word/diphthong",cta:"Open the word card",title:"Where it comes from · diphthong",body:"Greek di- = two + phthongos = sound/voice"},"wd-ophthalmology":{src:"concept:84:words:8:def",route:"#/word/ophthalmology",cta:"Open the word card",title:"ophthalmology",roman:"ah-p-th-uh-m-AH-l-uh-j-ee",body:"is the branch of medicine dealing with anatomy functions and diseases of the eye",clip:1},"wx-ophthalmology":{src:"concept:84:words:8:ex",route:"#/word/ophthalmology",cta:"Open the word card",title:"In a sentence · ophthalmology",body:"She chose to specialize in ophthalmology because she wanted to help patients who were losing their sight.",clip:1},"wh-ophthalmology":{src:"concept:84:words:8:hook",route:"#/word/ophthalmology",cta:"Open the word card",title:"Remember it · ophthalmology",body:"OPHTHALMOLOGY — the word itself needs an eye exam; spot the OPHTHALM hiding before -OLOGY."},"wo-ophthalmology":{src:"lore:ophthalmology:0",route:"#/word/ophthalmology",cta:"Open the word card",title:"Where it comes from · ophthalmology",body:"Greek ophthalmos = eye + logos = study"},"wd-phosphorus":{src:"concept:84:words:9:def",route:"#/word/phosphorus",cta:"Open the word card",title:"phosphorus",roman:"FAH-sfer-uhs",body:"a multivalent nonmetallic element of the nitrogen family that occurs commonly in inorganic phosphate rocks and as organic phosphates in all living cells; is highly reactive and occurs in several allotropic forms",clip:1},"wx-phosphorus":{src:"concept:84:words:9:ex",route:"#/word/phosphorus",cta:"Open the word card",title:"In a sentence · phosphorus",body:"Phosphorus is an essential element found in our bones and teeth, and it plays a key role in producing energy in our cells.",clip:1},"wh-phosphorus":{src:"concept:84:words:9:hook",route:"#/word/phosphorus",cta:"Open the word card",title:"Remember it · phosphorus",body:"PHOSPHORUS the element ends in -US like NUCLEUS — it's the glowing nucleus of fertilizers and matches."},"wo-phosphorus":{src:"lore:phosphorus:0",route:"#/word/phosphorus",cta:"Open the word card",title:"Where it comes from · phosphorus",body:"Greek phōsphoros = light-bearing (phōs=light + phoros=bearing)"},"wd-diphtheria":{src:"concept:84:words:10:def",route:"#/word/diphtheria",cta:"Open the word card",title:"diphtheria",roman:"dih-FTHIH-ree-ah",body:"acute contagious infection caused by the bacterium Corynebacterium diphtheriae; marked by the formation of a false membrane in the throat and other air passages causing difficulty in breathing",clip:1},"wx-diphtheria":{src:"concept:84:words:10:ex",route:"#/word/diphtheria",cta:"Open the word card",title:"In a sentence · diphtheria",body:"Before vaccines were available, diphtheria swept through schools and claimed the lives of many young children.",clip:1},"wh-diphtheria":{src:"concept:84:words:10:hook",route:"#/word/diphtheria",cta:"Open the word card",title:"Remember it · diphtheria",body:"DIPHTHERIA has a PH like PHarynx — it attacks your throat; remember the silent P in diPHtheria."},"wo-diphtheria":{src:"lore:diphtheria:0",route:"#/word/diphtheria",cta:"Open the word card",title:"Where it comes from · diphtheria",body:"Greek diphthera = leather hide (referring to the tough membrane formed in the throat)"},"wd-emphatic":{src:"concept:84:words:11:def",route:"#/word/emphatic",cta:"Open the word card",title:"emphatic",roman:"eh-MFA-tihk",body:"spoken with emphasis",clip:1},"wx-emphatic":{src:"concept:84:words:11:ex",route:"#/word/emphatic",cta:"Open the word card",title:"In a sentence · emphatic",body:"The coach gave an emphatic thumbs-up when her team scored the winning goal in the final seconds of the game.",clip:1},"wh-emphatic":{src:"concept:84:words:11:hook",route:"#/word/emphatic",cta:"Open the word card",title:"Remember it · emphatic",body:"An EMPHATIC statement puts EMPHASIS on every word"},"wo-emphatic":{src:"lore:emphatic:0",route:"#/word/emphatic",cta:"Open the word card",title:"Where it comes from · emphatic",body:"Greek emphasis = significance, from emphainein = to show in"},"wd-orphan":{src:"concept:84:words:12:def",route:"#/word/orphan",cta:"Open the word card",title:"orphan",roman:"AW-rfuhn",body:"a child who has lost both parents",clip:1},"wx-orphan":{src:"concept:84:words:12:ex",route:"#/word/orphan",cta:"Open the word card",title:"In a sentence · orphan",body:"The kind couple decided to adopt the orphan after meeting her at the community shelter.",clip:1},"wh-orphan":{src:"concept:84:words:12:hook",route:"#/word/orphan",cta:"Open the word card",title:"Remember it · orphan",body:"ORPHan: think of ORPH rhyming with MORPH — an orphan morphs into independence alone."},"wd-elephant":{src:"concept:84:words:13:def",route:"#/word/elephant",cta:"Open the word card",title:"elephant",roman:"EH-luh-fuhnt",body:"five-toed pachyderm",clip:1},"wx-elephant":{src:"concept:84:words:13:ex",route:"#/word/elephant",cta:"Open the word card",title:"In a sentence · elephant",body:"The elephant raised its enormous trunk and sprayed water over its dusty back.",clip:1},"wh-elephant":{src:"concept:84:words:13:hook",route:"#/word/elephant",cta:"Open the word card",title:"Remember it · elephant",body:"An ELEPHANT is ELEPH-ANT — imagine a giant ant named Eleph carrying a trunk."},"wo-elephant":{src:"lore:elephant:0",route:"#/word/elephant",cta:"Open the word card",title:"Where it comes from · elephant",body:"Greek elephas = elephant, ivory"},"wd-amphitheater":{src:"concept:84:words:14:def",route:"#/word/amphitheater",cta:"Open the word card",title:"amphitheater",roman:"A-m-f-uh-th-ee-uh-t-ur",body:"is an oval or round building with an open central area",clip:1},"wx-amphitheater":{src:"concept:84:words:14:ex",route:"#/word/amphitheater",cta:"Open the word card",title:"In a sentence · amphitheater",body:"The students sat in the grassy amphitheater and watched the outdoor Shakespeare performance under the stars.",clip:1},"wh-amphitheater":{src:"concept:84:words:14:hook",route:"#/word/amphitheater",cta:"Open the word card",title:"Remember it · amphitheater",body:"AMPHITHEATER = AMPHI + THEATER — seats go AROUND (amphi) the THEATER, so just add 'amphi' to a word you know!"},"wo-amphitheater":{src:"lore:amphitheater:0",route:"#/word/amphitheater",cta:"Open the word card",title:"Where it comes from · amphitheater",body:"Greek amphi = around + theatron = place for viewing"},"wd-epiphany":{src:"concept:84:words:15:def",route:"#/word/epiphany",cta:"Open the word card",title:"epiphany",roman:"ih-p-IH-f-uh-n-ee",body:"is a Christian festival",clip:1},"wx-epiphany":{src:"concept:84:words:15:ex",route:"#/word/epiphany",cta:"Open the word card",title:"In a sentence · epiphany",body:"Beyond its religious meaning, Maya used the word epiphany to describe the sudden moment she realized the solution to the math problem.",clip:1},"wh-epiphany":{src:"concept:84:words:15:hook",route:"#/word/epiphany",cta:"Open the word card",title:"Remember it · epiphany",body:"An EPIPHAny is when truth APPEARS (PHANy = phainein = show) — one 'n,' one shining moment of clarity."}});
